import { test, expect } from '@playwright/test';

test.describe('Field Validation Error Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display specific validation error for each invalid field', async ({ page }) => {
    // Intercept the API call to get form data
    await page.route('**/api/form-data', (route) => {
      route.abort('API call failed');
    });

    // Fill in the first field with invalid data
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Verify error message appears for email field
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    // Fill in the second field with invalid data
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('short');

    // Verify error message appears for password field
    const passwordError = page.getByText('Password must be at least 8 characters long');
    await expect(passwordError).toBeVisible();

    // Fill in the third field with valid data
    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('longpassword123');

    // Verify no error messages appear for valid fields
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).not.toBeVisible();

    const passwordError = page.getByText('Password must be at least 8 characters long');
    await expect(passwordError).not.toBeVisible();

    // Fill in the fourth field with invalid data
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('');

    // Verify error message appears for name field
    const nameError = page.getByText('Name is required');
    await expect(nameError).toBeVisible();

    // Fill in the fifth field with valid data
    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('123-456-7890');

    // Verify no error messages appear for valid fields
    const nameError = page.getByText('Name is required');
    await expect(nameError).not.toBeVisible();

    // Submit the form
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify error messages are cleared
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).not.toBeVisible();

    const passwordError = page.getByText('Password must be at least 8 characters long');
    await expect(passwordError).not.toBeVisible();

    const nameError = page.getByText('Name is required');
    await expect(nameError).not.toBeVisible();
  });

  test('should handle multiple validation errors and display all at once', async ({ page }) => {
    // Intercept the API call to get form data
    await page.route('**/api/form-data', (route) => {
      route.abort('API call failed');
    });

    // Fill in all fields with invalid data
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('short');

    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('short');

    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('');

    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('');

    // Verify all error messages appear
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    const passwordError = page.getByText('Password must be at least 8 characters long');
    await expect(passwordError).toBeVisible();

    const nameError = page.getByText('Name is required');
    await expect(nameError).toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();

    // Submit the form
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify error messages are cleared
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).not.toBeVisible();

    const passwordError = page.getByText('Password must be at least 8 characters long');
    await expect(passwordError).not.toBeVisible();

    const nameError = page.getByText('Name is required');
    await expect(nameError).not.toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();
  });
});
